#include <Snooker/AI/ShotEvaluation.h>
#include <fstream>
#include <iterator>
#include <iostream>
#define CHECK(x) do{if(!(x)){std::cerr<<"FAIL AI evaluation "<<__LINE__<<": "<<#x<<"; "<<error<<'\n';return 1;}}while(false)
std::string Read(const char*p){std::ifstream f(p);return {std::istreambuf_iterator<char>(f),{}};}
int main(int argc,char**argv){using namespace Snooker;std::string error;CHECK(argc==2);PhysicsBundle bundle;CHECK(PhysicsBundle::Deserialize(Read(argv[1]),bundle,&error));TableGeometry g;CHECK(GenerateTableGeometry(bundle.Table,bundle.Cushions,bundle.Pockets,bundle.Geometry,g,&error));BallState cue;cue.Id=1;cue.PositionMeters={0,-.6,cue.RadiusMeters};auto red=cue;red.Id=2;red.PositionMeters={0,-.78,red.RadiusMeters};PhysicsClock c;auto p=PhysicsSnapshot::Capture(c,{cue,red},bundle.Version,ESnapshotPhase::BeforeShot);BallDefinition cd;cd.Id=1;cd.Type=EBallType::Cue;cd.InitialPositionMeters=cue.PositionMeters;auto rd=cd;rd.Id=2;rd.Type=EBallType::Red;rd.InitialPositionMeters=red.PositionMeters;MatchState m;auto q=CreateAIStateQuery(m,p,{cd,rd},bundle.Cue,&error);CHECK(q);ShotCandidate candidate;CHECK(CreatePotCandidate(*q,g,2,2,1,candidate,&error));const auto hash=q->StateHash();ShotEvaluation result;CHECK(EvaluateCandidate(*q,bundle,candidate,result,&error));CHECK(result.Record.Result=="Settled"&&result.Record.Events.size()>2&&result.Detail.find("risk=")!=std::string::npos);PhysicsShotRecord replay;CHECK(ReplayShot(result.Record,replay,&error));CHECK(replay.Serialize()==result.Record.Serialize());CHECK(q->StateHash()==hash);auto saved=result.Record.Serialize();auto wrong=bundle;wrong.Version="wrong";CHECK(!EvaluateCandidate(*q,wrong,candidate,result,&error));CHECK(result.Record.Serialize()==saved);std::cout<<"PASS candidate shared-service evaluation, exact replay/event parity and immutable query\n";}
